const subject = $input.first().json.subject;

// Витягуємо номер угоди — все до " / "
const agreementNumber = subject.split(' / ')[0].trim();

return [{
  json: {
    agreementNumber,
    subject,
    messageId: $input.first().json.messageId,
    fromAddress: $input.first().json.from.value[0].address,
    emailText: $input.first().json.text || '',
    emailHtml: $input.first().json.html || '',
  }
}];

const { agreementNumber, messageId, fromAddress, emailText } = $('Парсинг теми та тіла').first().json;

// Беремо PDF як base64 рядок
const binaryData = $('Отримати лист').first().binary.attachment_0.data;

return [{
  json: {
    agreementNumber,
    messageId,
    fromAddress,
    emailText,
    pdfBase64: binaryData,
  }
}];

